SELECT e.name,p.oid IS NOT NULL AS present,NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE') AS denied_to_all_client_server_roles,NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee<>p.proowner) AS owner_only FROM (VALUES ('cohort_assert_record_parent_v1'),('cohort_guard_completion_record_identity_v1'),('cohort_sync_training_session_from_terminal_record'),('cohort_assert_completion_request_v1'),('cohort_complete_backfilled_fixed_occurrence_at'),('cohort_guard_direct_result_write_v1'),('cohort_guard_result_identity_v1'),('cohort_insert_training_session_result_tree'),('cohort_completion_programme_body_v1'),('cohort_completion_fixed_body_v1'),('cohort_completion_standalone_body_v1'),('cohort_completion_correction_body_v1'),('cohort_completion_backfill_body_v1')) e(name) LEFT JOIN pg_proc p ON p.pronamespace='public'::regnamespace AND p.proname=e.name ORDER BY e.name;
